-- CONFIG-CHANGE-AUDIT-1 + RESEARCH-CLUSTER-PROBES-1 (2026-10-26, pillars autonomy and cost; agent_issues 100626, 100623, 1000005; read for 100211, 100615, 100622, 100629, 1000029, 1000031, 100439, 100453).
-- Measured 2026-10-26 (SELECT only): ops_config research_daily_neurons was 600000 at 14:15Z on 2026-10-24 and 360000 again at 14:59Z with no record of who wrote either; three knobs
-- (research_daily_neurons, research_deferred_max, research_ready_cap) changed inside 20 minutes from different sessions, and two triggers had pinned research_ready_cap for days. ops_config
-- has no writer column and no history, so a metric delta cannot be attributed to a lever (issue 100626). Nothing logged a change. This file adds the log, in D1, where every writer (workers,
-- sessions, the dashboard, migrations) already goes through the table:
--   * triggers ops_config_research_audit_ins / _upd write one cloud_ops_events row of kind config-change for every research_* insert (replace included) and every value change, with the old and
--     new value and the writer's note (status ok with a note, warn without one), so an unattributed change is visible as a warn row; research_repo_sync_cursor and research_repo_catchup_at are
--     worker state written every tick and are left out;
--   * a research_config_audit row is inserted as the positive control (it fires the insert trigger once, so a probe can tell a live audit from an absent one);
--   * the contracts of issues 100623, 100626 and 1000005, born as the vacuous template (VACUOUS-PROBE-V3-1, "a doer replaces it with a probe that measures it"), get probes that measure
--     the defect: 100623 the watchdog filing a stall within 15 minutes of a budget hold after qnfo-cloud-ops 1.40.1 is live, 100626 an unlogged research_* change, 1000005 the publication
--     rate and the absence of busy answers from the watchdog;
--   * failure modes research-watchdog-held-stall and research-config-unlogged with their fm- detectors; a decision_log row; findings appended to issues 1000029, 100439 and 100453.
-- Not built, with the reason: a blocking single-writer guard on research_* (ANTIFRAGILE-1: no hold without live evidence, and every session writes this table, so a guard would fail writes
-- that today succeed; last-writer-wins stays but is now attributable), and updated_by / change_reason columns (ops_config.note carries the reason and the audit row carries it on).
-- Revert text for the audit: the Rollback header. The three contracts return to their born state from bak_20261026_research_cluster_contracts.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DROP TRIGGER IF EXISTS ops_config_research_audit_ins; DROP TRIGGER IF EXISTS ops_config_research_audit_upd; UPDATE remediation_contracts SET status = (SELECT b.status FROM bak_20261026_research_cluster_contracts b WHERE b.class = remediation_contracts.class), verify_probe = (SELECT b.verify_probe FROM bak_20261026_research_cluster_contracts b WHERE b.class = remediation_contracts.class), action = (SELECT b.action FROM bak_20261026_research_cluster_contracts b WHERE b.class = remediation_contracts.class), precondition = (SELECT b.precondition FROM bak_20261026_research_cluster_contracts b WHERE b.class = remediation_contracts.class), module = (SELECT b.module FROM bak_20261026_research_cluster_contracts b WHERE b.class = remediation_contracts.class), last_verdict = NULL WHERE class IN ('issue-100623', 'issue-100626', 'issue-1000005')
-- BACKUP: bak_20261026_research_cluster_contracts
-- Rollback note: the config-change events, the research_config_audit row, the failure_modes rows and the decision_log row stay (append-only or harmless); a trigger dropped by the Rollback stops new events only.

CREATE TABLE IF NOT EXISTS bak_20261026_research_cluster_contracts AS SELECT * FROM remediation_contracts WHERE issue_id IN (100623, 100626, 1000005);

CREATE TRIGGER IF NOT EXISTS ops_config_research_audit_ins AFTER INSERT ON ops_config WHEN NEW.key LIKE 'research_%' AND NEW.key NOT IN ('research_repo_sync_cursor', 'research_repo_catchup_at') BEGIN INSERT INTO cloud_ops_events (id, ts, kind, text, meta, job, status) VALUES ('cfg-' || lower(hex(randomblob(8))), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), 'config-change', 'CONFIG-CHANGE-AUDIT-1: ' || NEW.key || ' set to ' || substr(COALESCE(NEW.value, 'NULL'), 1, 120) || ' (insert or replace), note: ' || COALESCE(NULLIF(substr(NEW.note, 1, 160), ''), 'none'), json_object('key', NEW.key, 'new', substr(COALESCE(NEW.value, 'NULL'), 1, 400), 'note', NEW.note, 'op', 'insert'), 'ops_config', CASE WHEN COALESCE(NEW.note, '') = '' THEN 'warn' ELSE 'ok' END); END;

CREATE TRIGGER IF NOT EXISTS ops_config_research_audit_upd AFTER UPDATE ON ops_config WHEN NEW.key LIKE 'research_%' AND NEW.key NOT IN ('research_repo_sync_cursor', 'research_repo_catchup_at') AND NEW.value IS NOT OLD.value BEGIN INSERT INTO cloud_ops_events (id, ts, kind, text, meta, job, status) VALUES ('cfg-' || lower(hex(randomblob(8))), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), 'config-change', 'CONFIG-CHANGE-AUDIT-1: ' || NEW.key || ' changed from ' || substr(COALESCE(OLD.value, 'NULL'), 1, 120) || ' to ' || substr(COALESCE(NEW.value, 'NULL'), 1, 120) || ', note: ' || COALESCE(NULLIF(substr(NEW.note, 1, 160), ''), 'none'), json_object('key', NEW.key, 'old', substr(COALESCE(OLD.value, 'NULL'), 1, 400), 'new', substr(COALESCE(NEW.value, 'NULL'), 1, 400), 'note', NEW.note, 'old_note', OLD.note, 'op', 'update'), 'ops_config', CASE WHEN COALESCE(NEW.note, '') = '' OR NEW.note IS OLD.note THEN 'warn' ELSE 'ok' END); END;

INSERT OR IGNORE INTO ops_config (key, value, note) VALUES ('research_config_audit', 'on', 'CONFIG-CHANGE-AUDIT-1 (agent_issues 100626): every research_* insert or value change is logged as cloud_ops_events kind config-change by the triggers ops_config_research_audit_ins and ops_config_research_audit_upd. Put the reason in note when you write a key. This row is the positive control.');

UPDATE remediation_contracts SET status = 'active', module = 'doer-probe', precondition = 'qnfo-cloud-ops 1.40.1 is deployed (RESEARCH-WATCHDOG-HELD-1)', action = 'the watchdog skips a stage while the executor holds on purpose', last_verdict = NULL, attempts = 0, deferred_since = NULL, next_due_at = datetime('now'), verify_transport = 'd1-query',
  verify_probe = 'WITH d AS (SELECT MIN(deployed_at) AS t FROM deployment_history WHERE resource_name = ''qnfo-cloud-ops'' AND action = ''deploy'' AND version_id LIKE ''1.40.1%'') SELECT ''ok'' AS expected, CASE WHEN (SELECT t FROM d) IS NULL THEN ''pending: qnfo-cloud-ops 1.40.1 is not deployed'' WHEN (SELECT COUNT(*) FROM cloud_ops_events h WHERE h.kind = ''research-budget'' AND h.text LIKE ''daily budget exhausted%'' AND datetime(h.ts) > datetime((SELECT t FROM d))) = 0 THEN ''pending: no budget hold since the deploy to judge'' WHEN (SELECT COUNT(*) FROM cloud_ops_events w WHERE w.kind = ''research-watchdog'' AND w.text LIKE ''%no stage finished%'' AND datetime(w.ts) > datetime((SELECT t FROM d)) AND EXISTS (SELECT 1 FROM cloud_ops_events h WHERE h.kind = ''research-budget'' AND h.text LIKE ''daily budget exhausted%'' AND h.ts <= w.ts AND h.ts >= strftime(''%Y-%m-%dT%H:%M:%fZ'', datetime(w.ts, ''-15 minutes'')))) > 0 THEN ''the watchdog filed a stall within 15 minutes of a budget hold'' ELSE ''ok'' END AS observed'
WHERE class = 'issue-100623';

UPDATE remediation_contracts SET status = 'active', module = 'doer-probe', precondition = 'the audit triggers of migrations/2026-10-26-research-config-audit.sql are applied (CONFIG-CHANGE-AUDIT-1)', action = 'every research_* ops_config change is logged with its old value, new value and note', last_verdict = NULL, attempts = 0, deferred_since = NULL, next_due_at = datetime('now'), verify_transport = 'd1-query',
  verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM sqlite_master WHERE type = ''trigger'' AND name = ''ops_config_research_audit_upd'') THEN ''the update audit trigger is missing'' WHEN NOT EXISTS (SELECT 1 FROM cloud_ops_events WHERE kind = ''config-change'' AND text LIKE ''%research_config_audit%'') THEN ''the positive-control insert left no config-change event'' WHEN EXISTS (SELECT 1 FROM ops_config o WHERE o.key LIKE ''research_%'' AND o.key NOT IN (''research_repo_sync_cursor'', ''research_repo_catchup_at'') AND datetime(o.updated_at) > datetime(''now'', ''-1440 minutes'') AND datetime(o.updated_at) > datetime((SELECT MIN(ts) FROM cloud_ops_events WHERE kind = ''config-change''), ''+2 seconds'') AND NOT EXISTS (SELECT 1 FROM cloud_ops_events e WHERE e.kind = ''config-change'' AND e.text LIKE ''%'' || o.key || ''%'' AND e.ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', datetime(o.updated_at, ''-2 minutes'')))) THEN ''a research_* ops_config row changed without a config-change event'' ELSE ''ok'' END AS observed'
WHERE class = 'issue-100626';

UPDATE remediation_contracts SET status = 'active', module = 'doer-probe', precondition = 'single-flight lease disabled (leaseAcquire), pace gate replaced by the daily budget (DAILY-BUDGET-SCHEDULE-1), cost-first model order live (RESEARCH-COST-FIRST-1, 0.36.0)', action = 'research publishes at a rate the daily budget buys, and the watchdog never meets a busy executor', last_verdict = NULL, attempts = 0, deferred_since = NULL, next_due_at = datetime('now'), verify_transport = 'd1-query',
  verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM research_queue WHERE status = ''published'' AND published_at > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-1440 minutes'')) < 10 THEN ''pending: published in the last 1440 minutes = '' || (SELECT COUNT(*) FROM research_queue WHERE status = ''published'' AND published_at > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-1440 minutes'')) || '' (need 10)'' WHEN EXISTS (SELECT 1 FROM cloud_ops_events WHERE kind = ''research-watchdog'' AND (status = ''error'' OR text LIKE ''%HTTP 409%'') AND ts > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-1440 minutes'')) THEN ''the watchdog met a busy or failing executor in the last 1440 minutes'' ELSE ''ok'' END AS observed'
WHERE class = 'issue-1000005';

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('research-watchdog-held-stall', 'the research-exec watchdog files a stall (and forces a stage) while the executor holds its stages on purpose because the daily neuron budget is spent',
  'qnfo-cloud-ops researchWatchdogDecide treated a held stage as a stall: it read only the time of the last done event, so from 04:11Z on 2026-10-26, when COST-SUSTAIN-1 spent the day budget, it forced six stages per 60 minutes and wrote "no stage finished in 688 minutes" each time (agent_issues 100623)',
  'qnfo-cloud-ops 1.40.1 reads the executor''s own "daily budget exhausted" research-budget event and skips the kick while one is 15 minutes old or younger; an older hold means the tick stopped and the stall path runs as before',
  'fm-research-watchdog-held-stall: a research-watchdog "no stage finished" event with a daily-budget-exhausted event of the executor in the 15 minutes before it, inside 120 minutes',
  'fm-research-watchdog-held-stall', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), 100623,
  'cloud_ops_events kind research-watchdog with text "no stage finished" while kind research-budget "daily budget exhausted" was written in the 15 minutes before',
  'the watchdog logs one stall alarm every 10 minutes for the hours between the day budget being spent and 00:00 UTC',
  'research: watchdog noise and a daily forced no-op call; the real stall signal is buried');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-research-watchdog-held-stall', NULL, 'RESEARCH-WATCHDOG-HELD-1', 'failure-mode detector',
  'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM cloud_ops_events w WHERE w.kind = ''research-watchdog'' AND w.text LIKE ''%no stage finished%'' AND w.ts > strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-120 minutes'') AND EXISTS (SELECT 1 FROM cloud_ops_events h WHERE h.kind = ''research-budget'' AND h.text LIKE ''daily budget exhausted%'' AND h.ts <= w.ts AND h.ts >= strftime(''%Y-%m-%dT%H:%M:%fZ'', datetime(w.ts, ''-15 minutes'')))) AS TEXT) AS observed',
  'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode', datetime('now'));

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('research-config-unlogged', 'a research_* ops_config key changes and no event says who changed it or to what',
  'ops_config has key, value, note and updated_at only; three sessions rewrote research_daily_neurons, research_deferred_max and research_ready_cap within 20 minutes on 2026-10-24 and a budget change was reverted two minutes after it was made, with no trace (agent_issues 100626)',
  'triggers ops_config_research_audit_ins and _upd write a config-change event with the old value, new value and note for every research_* change; a warn row means the writer left no reason',
  'fm-research-config-unlogged: a research_* ops_config row with updated_at inside 1440 minutes and no config-change event within 2 minutes before it',
  'fm-research-config-unlogged', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), 100626,
  'ops_config rows with key LIKE research_% and a fresh updated_at that have no cloud_ops_events row of kind config-change',
  'a metric regression cannot be tied to the lever that moved it',
  'research: cost and throughput levers');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-research-config-unlogged', NULL, 'CONFIG-CHANGE-AUDIT-1', 'failure-mode detector',
  'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM ops_config o WHERE o.key LIKE ''research_%'' AND o.key NOT IN (''research_repo_sync_cursor'', ''research_repo_catchup_at'') AND datetime(o.updated_at) > datetime(''now'', ''-1440 minutes'') AND datetime(o.updated_at) > datetime((SELECT MIN(ts) FROM cloud_ops_events WHERE kind = ''config-change''), ''+2 seconds'') AND NOT EXISTS (SELECT 1 FROM cloud_ops_events e WHERE e.kind = ''config-change'' AND e.text LIKE ''%'' || o.key || ''%'' AND e.ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', datetime(o.updated_at, ''-2 minutes'')))) AS TEXT) AS observed',
  'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode', datetime('now'));

UPDATE agent_issues SET description = COALESCE(description, '') || char(10) || 'FINDING 2026-10-26 (session resolve-open-issues-520f91, measured on qnfo-audit): the waiver proposed here is declined and the probe is left as filed. REVISE-NO-UNREVISED-1 (0.13.0, issue 2211) replaced the earlier advance-on-noop because it published papers whose HARD review findings were never applied, and a waiver restores that behaviour (OUTPUT-QUALITY-LEDGER-1: a quality gate is not weakened to raise a count). The loop that does exist is narrower: revise-noop events fell from 264 a day on 10-20 to 6 on 10-26, and the revision rows rem-rev-b9f3a431 (parked 15 times in 2880 minutes) and rem-rev-67da34e4 keep returning because parkRearmTick counts a re-arm in research_queue.context.parkRearm and the revise, review and verify stages rewrite context without that key, so the PARK_REARM_MAX = 1 cap never holds. Lever: count park re-arms in terminal_rearms (shared with PARKED-REGROUND-1, cap TERMINAL_RECOVERY_MAX) so a row parks for good after its recoveries, with one event per exhausted row. That change is in qnfo-research-exec/worker.js. This probe stays open until it is live and the 48-hour window clears.' WHERE id = 1000029 AND status = 'open';

UPDATE agent_issues SET description = COALESCE(description, '') || char(10) || 'FINDING 2026-10-26 (session resolve-open-issues-520f91, q08-signal D1 engine_runs, last 3 days): the structural preflight shipped in q08-signal-engine 0.34.3 (structuralPreflight, PR 3916) is live, but it was not the gate that fails. Runs are 31 to 39 gate_failed a day with 85 to 139 compose calls and 198 to 315 panel and fact-check calls, and the leading errors are reader-panel quality failures after the ensemble edit ("the edited draft was still not worth reading", panel mean 2 to 3 of 5 against a bar of 4, and "final read: not worth publishing"). So the 0.012 pass rate and the 176,281 neurons per piece come from drafts below the panel bar, not from thin sources. Two levers were rejected: lowering the bar or publishing the best candidate on a timer (OUTPUT-QUALITY-LEDGER-1: no quality gate is weakened for cadence), and throttling attempts (neurons per piece would not move, pieces would fall). The lever that can move both metrics is spending less per failing draft: one cheap panel read of the first compose and an abort before the ensemble edit when it is under a floor, measured against engine_runs compose_calls and panel_calls per published piece.' WHERE id IN (100439, 100453) AND status = 'open';

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'session-resolve-open-issues-520f91',
  'the research-pipeline cluster (11 critical issues) is mostly code already merged by the code loop and waiting on a measurement, with three gaps no change covered: a watchdog that files a stall while the day budget is spent on purpose, no record of who writes research_* keys, and probes that measure nothing for three issues',
  'CONFIG-CHANGE-AUDIT-1 + RESEARCH-CLUSTER-PROBES-1: qnfo-cloud-ops 1.40.1 skips the forced stage while a daily-budget hold is 15 minutes old or younger; D1 triggers log every research_* ops_config change as a config-change event; doer probes replace the vacuous contracts of issues 100623, 100626 and 1000005; findings recorded on 1000029, 100439 and 100453 (waiver and lowered gate declined with reasons)',
  'qnfo-audit 2026-10-26 (SELECT only): research-budget "daily budget exhausted spent=405876 budget=360000" every 10 minutes from 04:11Z, research-watchdog 6 events an hour with "no stage finished in 688 minutes" and HTTP 200, cost-first model-order live from 09:50Z with no spend since the budget ran out, gpt-oss-120b 252k of 290k research-exec neurons on 10-26, revise-noop 264 a day on 10-20 and 6 on 10-26, q08 engine_runs 31 to 39 gate_failed a day, code_tasks merged for 100211, 100615, 100629, 1000005, 1000031 and 100453',
  'migration merged',
  'two triggers on ops_config (research_* keys only), one ops_config row, three remediation_contracts rows, two failure_modes rows with detectors, text appended to three issues, one watchdog decision in qnfo-cloud-ops',
  'the Rollback header of migrations/2026-10-26-research-config-audit.sql and the canonical revert of qnfo-cloud-ops 1.40.1',
  'every research_* change is attributable to its writer and reason, and the watchdog no longer reports a deliberate hold as a stall',
  'research-watchdog events with "no stage finished" during a budget hold fall from 6 per 60 minutes to 0 within 60 minutes of the 1.40.1 deploy, and a research_* change appears as a config-change event within a second',
  'none',
  'd1:qnfo-audit read-only, node:sqlite fixtures in migrations/research-config-audit.test.mjs, qnfo-cloud-ops/research-watchdog-held.test.mjs'
WHERE NOT EXISTS (SELECT 1 FROM decision_log WHERE instr(action, 'CONFIG-CHANGE-AUDIT-1 + RESEARCH-CLUSTER-PROBES-1:') = 1);
